require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../includes/auth.php';require_login();$page_title='Change Password';$current_page='password';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';if(!$current||!$new||!$confirm)$error='All fields are required.';elseif(strlen($new)<8)$error='New password must be at least 8 characters.';elseif($new!==$confirm)$error='New passwords do not match.';else{$s=$pdo->prepare('SELECT password FROM users WHERE id=?');$s->execute([$_SESSION['admin_id']]);$hash=$s->fetchColumn();if(!$hash||!password_verify($current,$hash))$error='Current password is incorrect.';else{$u=$pdo->prepare('UPDATE users SET password=? WHERE id=?');$u->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);flash('success','Password changed successfully.');redirect('change_password.php');}}}
